import random

import pytest


def make_ids(n: int, seed: int) -> list[int]:
    """Return n distinct non-negative record ids derived only from seed.

    Uses a private random.Random(seed) instance, so the result is the same
    on every run for the same seed and no global random state is touched.
    Raises ValueError if n < 0.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    rng = random.Random(seed)
    return rng.sample(range(1 << 31), n)


def test_make_ids_length_and_distinct() -> None:
    ids = make_ids(50, 7)
    assert len(ids) == 50
    assert len(set(ids)) == 50


def test_make_ids_all_non_negative() -> None:
    assert all(i >= 0 for i in make_ids(100, 3))


def test_make_ids_same_seed_same_output() -> None:
    assert make_ids(20, 42) == make_ids(20, 42)


def test_make_ids_different_seed_different_output() -> None:
    assert make_ids(20, 1) != make_ids(20, 2)


def test_make_ids_zero_returns_empty() -> None:
    assert make_ids(0, 99) == []


def test_make_ids_negative_n_raises() -> None:
    with pytest.raises(ValueError):
        make_ids(-1, 0)
